def verify_trust_presentations_synced_batch(
    self,
    tenant_id: str,
    signer_did: str,
    at: int,
    items: Any,
) -> List[Dict[str, Any]]:
    """批量以同一同步锚点快照验真未绑定外部演示，返回逐项结果。

    请求级结构（恰含 signer_did/at/presentations、类型与 1–100 项
    上限）由服务层校验（400）。本方法假定三者类型已合法：
    - 检查点语义与 :meth:`verify_trust_presentation_synced` 一致：
      来源未同步（含跨租户）抛 NotFoundError，at 超检查点抛
      ConflictError；合法时按 cursor<=at 解析一次快照，整批共用；
    - 逐项不短路、等长同序：项须恰含 presentation（JSON 对象）与
      challenge（非空字符串），否则该项
      ``{"valid": false, "reason": "请求项非法"}``；合法项复用
      单条 verify-synced 的演示九字段、holder_* 禁令、挑战、锚点、
      签名覆盖、格式、验签与期限规则及原因分类；
    - 成功项仅 ``{"valid": true}``，失败项键序为 valid、reason。

    纯只读：不改同步页、检查点、锚点、演示、状态或审计，结论随
    状态文件跨重启稳定。
    """
    latest = self._synced_anchor_events_latest(tenant_id, signer_did, at)
    results: List[Dict[str, Any]] = []
    for item in items:  # 逐项处理，失败不短路
        if (
            not isinstance(item, dict)
            or set(item) != {"presentation", "challenge"}
            or not isinstance(item["presentation"], dict)
            or not isinstance(item["challenge"], str)
            or not item["challenge"]
        ):
            results.append({"valid": False, "reason": "请求项非法"})
            continue
        valid, reason = self._verify_synced_presentation_against(
            latest, item["presentation"], item["challenge"]
        )
        if valid:
            results.append({"valid": True})
        else:
            results.append({"valid": False, "reason": reason})
    return results

def verify_trust_presentations_synced_batch_with_status(
    self,
    tenant_id: str,
    signer_did: str,
    at: int,
    items: Any,
) -> List[Dict[str, Any]]:
    """批量以同步锚点快照验真未绑定外部演示并合并批初状态快照。

    请求级结构（恰含 signer_did/at/presentations、类型与 1–100 项
    上限）由服务层校验（400）。本方法假定三者类型已合法：
    - 检查点语义与 :meth:`verify_trust_presentations_synced_batch`
      一致：来源未同步（含跨租户）抛 NotFoundError，at 超检查点
      抛 ConflictError，均先于逐项校验；合法时按 cursor<=at 解析
      一次锚点快照，并在批初同一次原子读取本租户
      ``credential_status_sync`` 状态快照，整批共用；
    - 逐项不短路、等长同序：项须恰含 presentation（JSON 对象）与
      challenge（非空字符串），否则该项
      ``{"valid": false, "reason": "请求项非法"}``；合法项复用
      单条 verify-synced 的未绑定九字段、holder_* 禁令、挑战、
      cursor<=at 末锚点、签名覆盖、格式、验签与期限规则及原因分类；
    - 验真通过后按演示的 ``(issuer_did, credential_id)`` 查批初
      状态快照：未同步（含属他租户）为“外部凭证状态未同步”，
      revoked 为“外部凭证已吊销：<保存的 reason>”（保存记录无
      reason 时用“未知原因”），unknown 为“外部凭证状态未知”，
      active 判成功；
    - 成功项仅 ``{"valid": true}``，失败项键序为 valid、reason。

    纯只读：不改同步页、检查点、锚点、演示、状态或审计，结论随
    状态文件跨重启稳定。
    """
    latest = self._synced_anchor_events_latest(tenant_id, signer_did, at)
    with self._lock:  # 批初一次原子读取本租户状态快照，整批共用
        bucket = self._bucket_locked(tenant_id)
        status_rows: Dict[str, Dict[str, Dict[str, Any]]] = {}
        if bucket is not None:
            for issuer, rows in (
                bucket.get("credential_status_sync", {}).items()
            ):
                status_rows[issuer] = {
                    cid: dict(row) for cid, row in rows.items()
                }
    results: List[Dict[str, Any]] = []
    for item in items:  # 逐项处理，失败不短路
        if (
            not isinstance(item, dict)
            or set(item) != {"presentation", "challenge"}
            or not isinstance(item["presentation"], dict)
            or not isinstance(item["challenge"], str)
            or not item["challenge"]
        ):
            results.append({"valid": False, "reason": "请求项非法"})
            continue
        presentation = item["presentation"]
        valid, reason = self._verify_synced_presentation_against(
            latest, presentation, item["challenge"]
        )
        if valid:
            row = status_rows.get(
                presentation["issuer_did"], {}
            ).get(presentation["credential_id"])
            if row is None:
                valid, reason = False, "外部凭证状态未同步"
            else:
                status = row.get("status")
                if status == "revoked":
                    saved_reason = row.get("reason")
                    if not saved_reason:
                        saved_reason = "未知原因"
                    valid, reason = (
                        False,
                        f"外部凭证已吊销：{saved_reason}",
                    )
                elif status != "active":
                    # status 仅可能为 active/revoked/unknown
                    # （同步入口已约束）。
                    valid, reason = False, "外部凭证状态未知"
        if valid:
            results.append({"valid": True})
        else:
            results.append({"valid": False, "reason": reason})
    return results

def verify_trust_proof(
    self,
    tenant_id: str,
    data: Any,
) -> Tuple[bool, str]:
    """验证未在本租户保存的外部谓词证明，返回 (是否有效, 失败原因)。

    请求体须恰含 proof（对象）、challenge（非空字符串）与
    source_tenant_id（非空字符串）。proof 须恰为 prove 响应九字段：
    proof_id、credential_id、issuer_did（非空字符串）、
    issuer_key_version（非布尔正整数）、predicates、results、
    challenge/expires_at/proof（非空字符串）。results 与 predicates
    等长且仅含布尔；请求 challenge 须等于证明对象 challenge。
    predicates 项须恰含 path、op 及可选 value；op 限
    exists/eq/gte/lte，exists 禁 value，其余必填 value，gte/lte 的
    value 为非布尔数字；path 须以 / 开头、RFC6901 转义合法且无重复
    或祖先重叠（不校验 claims 命中、数组路径或命中值类型，也不重算
    results）。

    校验顺序：请求 -> 证明字段与挑战 -> 锚点 -> 签名格式 ->
    ES256 验签（覆盖除 proof 外八字段并加入
    tenant_id=source_tenant_id 的规范化 JSON）-> 期限。锚点按当前
    租户 (issuer_did, issuer_key_version) 查找，仅 active 的 P-256
    公钥可用。expires_at 须为 UTC 秒精度 Z 格式，到期返回
    “证明已过期”。原验真成功后按当前租户查 issuer_did 外部停用
    通告，命中返回“外部签发DID已停用：<reason>”，仅他租户有通告
    不影响结论。只读：不消费、不登记任何资源、不写状态/历史/审计，
    绝不向上抛异常。
    """
    # 1. 请求结构：恰含 proof、challenge、source_tenant_id。
    if not isinstance(data, dict):
        return False, "请求不合法: 请求体必须为 JSON 对象"
    request_fields = {"proof", "challenge", "source_tenant_id"}
    if set(data) != request_fields:
        missing = sorted(request_fields - set(data))
        if missing:
            return False, f"请求缺少字段: {', '.join(missing)}"
        extra = sorted(set(data) - request_fields)
        return False, f"请求含多余字段: {', '.join(extra)}"
    proof = data["proof"]
    request_challenge = data["challenge"]
    source_tenant_id = data["source_tenant_id"]
    if not isinstance(proof, dict):
        return False, "请求不合法: 字段 proof 必须为 JSON 对象"
    if not isinstance(request_challenge, str) or not request_challenge:
        return False, "请求不合法: 字段 challenge 必须为非空字符串"
    if not isinstance(source_tenant_id, str) or not source_tenant_id:
        return False, (
            "请求不合法: 字段 source_tenant_id 必须为非空字符串"
        )

    # 2. 证明字段与挑战。
    required_fields = {
        "proof_id",
        "credential_id",
        "issuer_did",
        "issuer_key_version",
        "predicates",
        "results",
        "challenge",
        "expires_at",
        "proof",
    }
    if set(proof) != required_fields:
        missing = sorted(required_fields - set(proof))
        if missing:
            return False, f"证明缺少字段: {', '.join(missing)}"
        extra = sorted(set(proof) - required_fields)
        return False, f"证明含多余字段: {', '.join(extra)}"
    for field in ("proof_id", "credential_id", "issuer_did"):
        value = proof[field]
        if not isinstance(value, str) or not value:
            return False, f"证明字段 {field} 必须为非空字符串"
    key_version = proof["issuer_key_version"]
    if (
        not isinstance(key_version, int)
        or isinstance(key_version, bool)
        or key_version < 1
    ):
        return False, "证明字段 issuer_key_version 必须为正整数"
    predicates = proof["predicates"]
    if not isinstance(predicates, list) or not predicates:
        return False, "证明字段 predicates 必须为非空数组"
    seen_tokens: List[Tuple[str, ...]] = []
    for item in predicates:
        if not isinstance(item, dict):
            return False, "证明 predicates 元素必须为 JSON 对象"
        if set(item) - {"path", "op", "value"}:
            extra = sorted(set(item) - {"path", "op", "value"})
            return False, (
                f"证明 predicates 元素含多余字段: {', '.join(extra)}"
            )
        if "path" not in item:
            return False, "证明 predicates 元素缺少字段: path"
        if "op" not in item:
            return False, "证明 predicates 元素缺少字段: op"
        op = item["op"]
        if op not in _PREDICATE_OPS:
            return False, (
                f"证明 predicates 元素 op 非法: {op!r}"
                "（仅支持 exists/eq/gte/lte）"
            )
        if op == "exists":
            if "value" in item:
                return False, (
                    "证明 predicates 元素 op 为 exists 时禁止 value 字段"
                )
        elif "value" not in item:
            return False, (
                f"证明 predicates 元素 op 为 {op} 时缺少字段: value"
            )
        elif op in ("gte", "lte") and not _is_number(item["value"]):
            return False, (
                f"证明 predicates 元素 op 为 {op} 时 value 必须为非布尔数字"
            )
        # 仅做指针语法与重叠校验：不查 claims 命中、不判数组路径。
        try:
            tokens = _parse_pointer(item["path"], "证明 predicates")
        except ValidationError as exc:
            return False, str(exc)
        if tokens in seen_tokens:
            return False, (
                f"证明 predicates 路径重复: {item['path']!r}"
            )
        for existing in seen_tokens:
            if tokens[: len(existing)] == existing:
                return False, (
                    "证明 predicates 路径存在祖先重叠: "
                    f"{item['path']!r} 被已选路径覆盖"
                )
            if existing[: len(tokens)] == tokens:
                return False, (
                    "证明 predicates 路径存在祖先重叠: "
                    f"已选路径被 {item['path']!r} 覆盖"
                )
        seen_tokens.append(tokens)
    results = proof["results"]
    if not isinstance(results, list) or len(results) != len(predicates):
        return False, (
            "证明字段 results 必须为与 predicates 等长的数组"
        )
    if any(not isinstance(item, bool) for item in results):
        return False, "证明字段 results 仅能包含布尔值"
    for field in ("challenge", "expires_at", "proof"):
        value = proof[field]
        if not isinstance(value, str) or not value:
            return False, f"证明字段 {field} 必须为非空字符串"
    if request_challenge != proof["challenge"]:
        return False, "挑战不匹配: 请求 challenge 与证明 challenge 不一致"

    # 3. 锚点：当前租户 (issuer_did, issuer_key_version)，仅 active。
    issuer_did = proof["issuer_did"]
    with self._lock:
        bucket = self._bucket_locked(tenant_id)
        anchors = (
            bucket["trust_anchors"].get(issuer_did)
            if bucket is not None else None
        )
        row = (
            anchors.get(str(key_version))
            if anchors is not None else None
        )
        public_pem = row.get("public_key", "") if row is not None else ""
        status = row.get("status", "active") if row is not None else None
        uses = row.get("uses") if row is not None else None
    if row is None:
        return False, f"锚点不存在: {issuer_did}#{key_version}"
    if status == "revoked":
        return False, f"锚点已吊销: {issuer_did}#{key_version}"
    # 用途白名单：active 锚点无 proof 用途时按锚点不可用处理
    if uses is not None and "proof" not in uses:
        return False, f"锚点不存在: {issuer_did}#{key_version}"
    try:
        crypto.validate_public_key_pem(public_pem)
    except (ValueError, TypeError):
        return False, (
            f"锚点公钥不可用: {issuer_did}#{key_version} 不是合法 P-256 公钥"
        )

    # 4/5. 签名格式与密码学验签：覆盖除 proof 外八字段，并加入
    # tenant_id=source_tenant_id 后按规范化 JSON 验签。
    signature = proof["proof"]
    message = {k: v for k, v in proof.items() if k != "proof"}
    message["tenant_id"] = source_tenant_id
    try:
        crypto.verify(message, signature, public_pem)
    except crypto.MalformedSignature:
        return False, "签名格式错误: 不是合法的 ES256 签名编码"
    except crypto.InvalidSignature:
        return False, "签名校验失败，证明内容或签名可能被改动"
    except Exception:  # noqa: BLE001 验签绝不向上抛错或泄露内部细节
        return False, "签名校验失败: 验签过程发生内部错误"

    # 6. 期限：expires_at 须为 UTC 秒精度 Z 格式；当前时间达到它即
    # 过期。只读，不消费、不写任何状态、不记审计。
    expires_value = proof["expires_at"]
    if not _UTC_Z_SHAPE_RE.match(expires_value):
        return False, (
            "证明字段 expires_at 必须为 UTC 秒精度 Z 格式"
            "（YYYY-MM-DDTHH:MM:SSZ）"
        )
    try:
        expires_dt = _parse_utc_z(expires_value)
    except ValueError:
        return False, (
            "证明字段 expires_at 必须为 UTC 秒精度 Z 格式"
            "（YYYY-MM-DDTHH:MM:SSZ）"
        )
    if datetime.now(timezone.utc) >= expires_dt:
        return False, "证明已过期"

    # 7. 原验真成功后、合并凭证状态前查本租户 issuer_did 外部停用
    #    通告：命中返回“外部签发DID已停用：<reason>”；无通告或仅他
    #    租户有通告维持原结论。只读，不写状态、不记审计。
    deactivation_reason = self._external_did_deactivation_reason(
        tenant_id, issuer_did, EXTERNAL_ISSUER_DID_DEACTIVATED_REASON_PREFIX
    )
    if deactivation_reason is not None:
        return False, deactivation_reason
    return True, ""

def verify_trust_proof_synced(
    self,
    tenant_id: str,
    signer_did: str,
    at: int,
    proof: Any,
    challenge: Any,
    source_tenant_id: Any,
) -> Tuple[bool, str]:
    """以同步锚点验真外部谓词证明，返回 (是否有效, 失败原因)。

    """以同步锚点验真外部谓词证明，返回 (是否有效, 失败原因)。

    请求结构（恰含 signer_did/at/proof/challenge/source_tenant_id
    及类型）由服务层校验（400）。本方法假定五键类型已合法：
    - 该签名方在本租户无同步检查点（含跨租户）抛 NotFoundError；
      at 超过检查点抛 ConflictError；
    - 证明九字段、predicates、results、challenge 与 expires_at
      规则沿用 :meth:`verify_trust_proof`；
    - 锚点取该来源 cursor<=at 的已同步事件，以 (issuer_did, 版本)
      最后事件为准；缺失、非 active 或 uses 无 proof 均返回
      (False, "同步锚点不可用")；
    - proof 须为 ES256、64 字节裸 R||S 无填充 base64url，覆盖除
      proof 外八字段并加入 tenant_id=source_tenant_id 的规范化
      JSON；格式错、验签错、到期依次返回 “签名格式错误”/
      “签名校验失败”/“证明已过期”，较早错误优先。

    校验顺序：请求 -> 证明字段 -> 挑战 -> 锚点 -> 签名格式 ->
    验签 -> 期限。纯只读：不改同步页、检查点、锚点、证明、状态或
    审计，结论随状态文件跨重启稳定。
    """
    latest = self._synced_anchor_events_latest(tenant_id, signer_did, at)
    return self._verify_synced_proof_against(
        latest, proof, challenge, source_tenant_id
    )

@staticmethod
def _verify_synced_proof_against(
    latest: Dict[Tuple[str, int], Dict[str, Any]],
    proof: Any,
    challenge: Any,
    source_tenant_id: Any,
) -> Tuple[bool, str]:
    """在已解析的同步锚点快照上验真一条外部谓词证明（只读）。

    假定 proof 为 JSON 对象、challenge 与 source_tenant_id 均为非空
    字符串；证明九字段、谓词/results、RFC6901 路径、挑战、锚点、
    签名覆盖（去掉 proof 后的八字段并加入
    tenant_id=source_tenant_id 的规范化 JSON）、签名格式、验签与
    期限规则及原因分类与 :meth:`verify_trust_proof_synced` 完全
    一致，供单条与批量同步锚点验真共用同一快照。
    """
    # 证明字段（沿用 /v1/trust/proofs/verify 的分类原因）：恰为
    # prove 响应九字段。
    required_fields = {
        "proof_id",
        "credential_id",
        "issuer_did",
        "issuer_key_version",
        "predicates",
        "results",
        "challenge",
        "expires_at",
        "proof",
    }
    if set(proof) != required_fields:
        missing = sorted(required_fields - set(proof))
        if missing:
            return False, f"证明缺少字段: {', '.join(missing)}"
        extra = sorted(set(proof) - required_fields)
        return False, f"证明含多余字段: {', '.join(extra)}"
    for field in ("proof_id", "credential_id", "issuer_did"):
        value = proof[field]
        if not isinstance(value, str) or not value:
            return False, f"证明字段 {field} 必须为非空字符串"
    key_version = proof["issuer_key_version"]
    if (
        not isinstance(key_version, int)
        or isinstance(key_version, bool)
        or key_version < 1
    ):
        return False, "证明字段 issuer_key_version 必须为正整数"
    predicates = proof["predicates"]
    if not isinstance(predicates, list) or not predicates:
        return False, "证明字段 predicates 必须为非空数组"
    seen_tokens: List[Tuple[str, ...]] = []
    for item in predicates:
        if not isinstance(item, dict):
            return False, "证明 predicates 元素必须为 JSON 对象"
        if set(item) - {"path", "op", "value"}:
            extra = sorted(set(item) - {"path", "op", "value"})
            return False, (
                f"证明 predicates 元素含多余字段: {', '.join(extra)}"
            )
        if "path" not in item:
            return False, "证明 predicates 元素缺少字段: path"
        if "op" not in item:
            return False, "证明 predicates 元素缺少字段: op"
        op = item["op"]
        if op not in _PREDICATE_OPS:
            return False, (
                f"证明 predicates 元素 op 非法: {op!r}"
                "（仅支持 exists/eq/gte/lte）"
            )
        if op == "exists":
            if "value" in item:
                return False, (
                    "证明 predicates 元素 op 为 exists 时禁止 value 字段"
                )
        elif "value" not in item:
            return False, (
                f"证明 predicates 元素 op 为 {op} 时缺少字段: value"
            )
        elif op in ("gte", "lte") and not _is_number(item["value"]):
            return False, (
                f"证明 predicates 元素 op 为 {op} 时 value 必须为非布尔数字"
            )
        # 仅做指针语法与重叠校验：不查 claims 命中、不判数组路径。
        try:
            tokens = _parse_pointer(item["path"], "证明 predicates")
        except ValidationError as exc:
            return False, str(exc)
        if tokens in seen_tokens:
            return False, (
                f"证明 predicates 路径重复: {item['path']!r}"
            )
        for existing in seen_tokens:
            if tokens[: len(existing)] == existing:
                return False, (
                    "证明 predicates 路径存在祖先重叠: "
                    f"{item['path']!r} 被已选路径覆盖"
                )
            if existing[: len(tokens)] == tokens:
                return False, (
                    "证明 predicates 路径存在祖先重叠: "
                    f"已选路径被 {item['path']!r} 覆盖"
                )
        seen_tokens.append(tokens)
    results = proof["results"]
    if not isinstance(results, list) or len(results) != len(predicates):
        return False, (
            "证明字段 results 必须为与 predicates 等长的数组"
        )
    if any(not isinstance(item, bool) for item in results):
        return False, "证明字段 results 仅能包含布尔值"
    for field in ("challenge", "expires_at", "proof"):
        value = proof[field]
        if not isinstance(value, str) or not value:
            return False, f"证明字段 {field} 必须为非空字符串"

    # 挑战：请求 challenge 须等于证明 challenge。
    if challenge != proof["challenge"]:
        return False, "挑战不匹配: 请求 challenge 与证明 challenge 不一致"

    # 同步锚点：(issuer_did, 版本) 最后事件，须 active 且含 proof
    # 用途。
    issuer_did = proof["issuer_did"]
    anchor = latest.get((issuer_did, key_version))
    if (
        anchor is None
        or anchor["status"] != "active"
        or "proof" not in anchor["uses"]
    ):
        return False, SYNCED_ANCHOR_UNAVAILABLE_REASON
    public_pem = anchor["public_key"]
    try:
        crypto.validate_public_key_pem(public_pem)
    except (ValueError, TypeError):
        return False, SYNCED_ANCHOR_UNAVAILABLE_REASON

    # 签名格式（严格：64 字节裸 R||S 无填充 base64url）与密码学
    # 验签：覆盖范围沿用 /v1/trust/proofs/verify——去掉 proof 后的
    # 八个字段并加入 tenant_id=source_tenant_id。
    signature = proof["proof"]
    message = {k: v for k, v in proof.items() if k != "proof"}
    message["tenant_id"] = source_tenant_id
    try:
        crypto.validate_signature_format_strict(signature)
    except crypto.MalformedSignature:
        return False, IMPORTED_SIGNATURE_MALFORMED_REASON
    try:
        crypto.verify(message, signature, public_pem)
    except crypto.MalformedSignature:
        return False, IMPORTED_SIGNATURE_MALFORMED_REASON
    except crypto.InvalidSignature:
        return False, IMPORTED_SIGNATURE_INVALID_REASON
    except Exception:  # noqa: BLE001 验签绝不向上抛错或泄露内部细节
        return False, IMPORTED_SIGNATURE_INVALID_REASON

    # 期限：expires_at 须为 UTC 秒精度 Z 格式；当前时间达到它即
    # 过期。规则同 /v1/trust/proofs/verify。
    expires_value = proof["expires_at"]
    if (
        not isinstance(expires_value, str)
        or not _UTC_Z_SHAPE_RE.match(expires_value)
    ):
        return False, (
            "证明字段 expires_at 必须为 UTC 秒精度 Z 格式"
            "（YYYY-MM-DDTHH:MM:SSZ）"
        )
    try:
        expires_dt = _parse_utc_z(expires_value)
    except ValueError:
        return False, (
            "证明字段 expires_at 必须为 UTC 秒精度 Z 格式"
            "（YYYY-MM-DDTHH:MM:SSZ）"
        )
    if datetime.now(timezone.utc) >= expires_dt:
        return False, "证明已过期"
    return True, ""

def verify_trust_proofs_synced_batch(
    self,
    tenant_id: str,
    signer_did: str,
    at: int,
    items: Any,
) -> List[Dict[str, Any]]:
    """批量以同一同步锚点快照验真外部谓词证明，返回逐项结果。

    请求级结构（恰含 signer_did/at/proofs、类型与 1–100 项上限）
    由服务层校验（400）。本方法假定三者类型已合法：
    - 检查点语义与 :meth:`verify_trust_proof_synced` 一致：来源未
      同步（含跨租户）抛 NotFoundError，at 超检查点抛
      ConflictError；合法时按 cursor<=at 解析一次快照，整批共用；
    - 逐项不短路、等长同序：项须恰含 proof（JSON 对象）、
      challenge（非空字符串）、source_tenant_id（非空字符串），
      否则该项 ``{"valid": false, "reason": "请求项非法"}``；合法
      项复用单条 verify-synced 的证明九字段、谓词/results、
      RFC6901 路径、挑战、签名覆盖、锚点、格式、验签与期限规则及
      原因分类；
    - 成功项仅 ``{"valid": true}``，失败项键序为 valid、reason。

    纯只读：不改同步页、检查点、锚点、证明、状态或审计，结论随
    状态文件跨重启稳定。
    """
    latest = self._synced_anchor_events_latest(tenant_id, signer_did, at)
    results: List[Dict[str, Any]] = []
    for item in items:  # 逐项处理，失败不短路
        if (
            not isinstance(item, dict)
            or set(item) != {"proof", "challenge", "source_tenant_id"}
            or not isinstance(item["proof"], dict)
            or not isinstance(item["challenge"], str)
            or not item["challenge"]
            or not isinstance(item["source_tenant_id"], str)
            or not item["source_tenant_id"]
        ):
            results.append({"valid": False, "reason": "请求项非法"})
            continue
        valid, reason = self._verify_synced_proof_against(
            latest,
            item["proof"],
            item["challenge"],
            item["source_tenant_id"],
        )
        if valid:
            results.append({"valid": True})
        else:
            results.append({"valid": False, "reason": reason})
    return results

def verify_trust_proof_with_status(
    self,
    tenant_id: str,
    data: Any,
) -> Tuple[bool, str]:
    """外部谓词证明验真并合并本地同步状态判定（只读）。

    先按 :meth:`verify_trust_proof` 的全部规则完成验真（请求结构 →
    证明字段与挑战 → 锚点 → 签名格式 → ES256 验签 → 期限），失败
    原样返回 ``(False, 原因)``，保持既有优先级与中文原因分类。

    验真通过后按当前租户 ``(issuer_did, credential_id)`` 双键只读
    查询 ``credential_status_sync`` 同步记录：
      - 未同步（含属他租户）：``(False, "外部凭证状态未同步")``；
      - active：``(True, "")``；
      - revoked：``(False, "外部凭证已吊销：<保存的 reason>")``，
        保存记录无 reason 时用“未知原因”；
      - unknown：``(False, "外部凭证状态未知")``。

    纯只读：不消费、不登记任何资源、不写状态/历史/审计。
    """
    valid, reason = self.verify_trust_proof(tenant_id, data)
    if not valid:
        return False, reason

    proof = data["proof"]
    issuer_did = proof["issuer_did"]
    credential_id = proof["credential_id"]
    with self._lock:
        bucket = self._bucket_locked(tenant_id)
        row = None
        if bucket is not None:
            row = (
                bucket.get("credential_status_sync", {})
                .get(issuer_did, {})
                .get(credential_id)
            )
    if row is None:
        return False, "外部凭证状态未同步"
    status = row.get("status")
    if status == "active":
        return True, ""
    if status == "revoked":
        saved_reason = row.get("reason")
        if not saved_reason:
            saved_reason = "未知原因"
        return False, f"外部凭证已吊销：{saved_reason}"
    # status 仅可能为 active/revoked/unknown（同步入口已约束）。
    return False, "外部凭证状态未知"

def verify_trust_proofs_batch(
    self,
    tenant_id: str,
    data: Any,
) -> Tuple[bool, str, List[Dict[str, Any]]]:
    """批量验证外部谓词证明，返回 (请求是否合法, 请求级原因, 逐项结果)。

    请求体须恰为 ``{"proofs": [项...]}``：数组非空且不超过 100 项。
    请求级结构不合法（非对象、字段缺失或多余、proofs 非数组、空数组
    或超过上限）时返回 ``(False, "请求...", [])``，由调用方回
    ``{"results": [], "reason": ...}``。

    请求级合法时逐项复用 :meth:`verify_trust_proof`（与单项接口完全
    一致的请求、证明字段、挑战、锚点、签名与期限规则），按输入顺序
    收集结果，失败不短路：成功项 ``{"valid": true}``，失败项
    ``{"valid": false, "reason": ...}``。只读，不消费、不登记任何
    资源、不写状态/历史/审计。
    """
    if not isinstance(data, dict):
        return False, "请求不合法: 请求体必须为 JSON 对象", []
    if set(data) != {"proofs"}:
        missing = [f for f in ("proofs",) if f not in data]
        if missing:
            return False, (
                f"请求缺少字段: {', '.join(missing)}"
            ), []
        extra = sorted(set(data) - {"proofs"})
        return False, f"请求含多余字段: {', '.join(extra)}", []
    proofs = data["proofs"]
    if not isinstance(proofs, list):
        return False, "请求不合法: 字段 proofs 必须为数组", []
    if not proofs:
        return False, "请求不合法: proofs 数组不能为空", []
    if len(proofs) > 100:
        return False, (
            f"请求不合法: proofs 数组不能超过 100 项（当前 {len(proofs)} 项）"
        ), []

    results: List[Dict[str, Any]] = []
    for item in proofs:  # 顺序校验，失败不短路
        valid, reason = self.verify_trust_proof(tenant_id, item)
        if valid:
            results.append({"valid": True})
        else:
            results.append(
                {"valid": False, "reason": reason or "验签失败"}
            )
    return True, "", results

